6: // tree.
7: //
8: // +build !windows
9: 
10: package pcap
11: 
12: import (
13: 	"errors"
14: 	"os"
15: 	"sync"
16: 	"syscall"
17: 	"time"
18: 	"unsafe"
19: 
20: 	"github.com/google/gopacket"
21: 
22: 	"github.com/google/gopacket/layers"
23: )
24: 
25: /*
26: #cgo solaris LDFLAGS: -L /opt/local/lib -lpcap
27: #cgo linux LDFLAGS: -lpcap
28: #cgo dragonfly LDFLAGS: -lpcap
29: #cgo freebsd LDFLAGS: -lpcap
30: #cgo openbsd LDFLAGS: -lpcap
31: #cgo netbsd LDFLAGS: -lpcap
32: #cgo darwin LDFLAGS: -lpcap
33: #include <stdlib.h>
34: #include <pcap.h>
35: #include <stdint.h>
36: #include <poll.h>
37: 
38: // Some old versions of pcap don't define this constant.
39: #ifndef PCAP_NETMASK_UNKNOWN
40: #define PCAP_NETMASK_UNKNOWN 0xffffffff
41: #endif
42: 
43: // libpcap doesn't actually export its version in a #define-guardable way,
44: // so we have to use other defined things to differentiate versions.
45: // We assume at least libpcap v1.1 at the moment.
46: // See http://upstream-tracker.org/versions/libpcap.html
47: 
48: #ifndef PCAP_ERROR_TSTAMP_PRECISION_NOTSUP  // < v1.5
49: #define PCAP_ERROR_TSTAMP_PRECISION_NOTSUP -12
50: 
51: int pcap_set_immediate_mode(pcap_t *p, int mode) {
52:   return PCAP_ERROR;
53: }
54: 
55: //  libpcap version < v1.5 doesn't have timestamp precision (everything is microsecond)
56: //
57: //  This means *_tstamp_* functions and macros are missing. Therefore, we emulate these
58: //  functions here and pretend the setting the precision works. This is actually the way
59: //  the pcap_open_offline_with_tstamp_precision works, because it doesn't return an error
60: //  if it was not possible to set the precision, which depends on support by the given file.
61: //  => The rest of the functions always pretend as if they could set nano precision and
62: //  verify the actual precision with pcap_get_tstamp_precision, which is emulated for <v1.5
63: //  to always return micro resolution.
64: 
65: #define PCAP_TSTAMP_PRECISION_MICRO	0
