128: // The things we do to avoid pointers escaping to the heap...
129: // According to https://github.com/the-tcpdump-group/libpcap/blob/1131a7c26c6f4d4772e4a2beeaf7212f4dea74ac/pcap.c#L398-L406 ,
130: // the return value of pcap_next_ex could be greater than 1 for success.
131: // Let's just make it 1 if it comes bigger than 1.
132: int pcap_next_ex_escaping(pcap_t *p, uintptr_t pkt_hdr, uintptr_t pkt_data) {
133:   int ex = pcap_next_ex(p, (struct pcap_pkthdr**)(pkt_hdr), (const u_char**)(pkt_data));
134:   if (ex > 1) {
135:     ex = 1;
136:   }
137:   return ex;
138: }
