144: // pcap_wait returns when the next packet is available or the timeout expires.
145: // Since it uses pcap_get_selectable_fd, it will not work in Windows.
146: int pcap_wait(pcap_t *p, int msec) {
147: 	struct pollfd fds[1];
148: 	int fd;
149: 
150: 	fd = pcap_get_selectable_fd(p);
151: 	if(fd < 0) {
152: 		return fd;
153: 	}
154: 
155: 	fds[0].fd = fd;
156: 	fds[0].events = POLLIN;
157: 
158: 	if(msec != 0) {
159: 		return poll(fds, 1, msec);
160: 	}
161: 
162: 	// block indefinitely if no timeout provided
163: 	return poll(fds, 1, -1);
164: }
165: 
