294: func (p pcapBpfProgram) toBPFInstruction() []BPFInstruction {
295: 	bpfInsn := (*[bpfInstructionBufferSize]C.struct_bpf_insn)(unsafe.Pointer(p.bf_insns))[0:p.bf_len:p.bf_len]
296: 	bpfInstruction := make([]BPFInstruction, len(bpfInsn), len(bpfInsn))
297: 
298: 	for i, v := range bpfInsn {
299: 		bpfInstruction[i].Code = uint16(v.code)
300: 		bpfInstruction[i].Jt = uint8(v.jt)
301: 		bpfInstruction[i].Jf = uint8(v.jf)
302: 		bpfInstruction[i].K = uint32(v.k)
303: 	}
304: 	return bpfInstruction
305: }
