307: func pcapBpfProgramFromInstructions(bpfInstructions []BPFInstruction) pcapBpfProgram {
308: 	var bpf pcapBpfProgram
309: 	bpf.bf_len = C.u_int(len(bpfInstructions))
310: 	cbpfInsns := C.calloc(C.size_t(len(bpfInstructions)), C.size_t(unsafe.Sizeof(bpfInstructions[0])))
311: 	gbpfInsns := (*[bpfInstructionBufferSize]C.struct_bpf_insn)(cbpfInsns)
312: 
313: 	for i, v := range bpfInstructions {
314: 		gbpfInsns[i].code = C.u_short(v.Code)
315: 		gbpfInsns[i].jt = C.u_char(v.Jt)
316: 		gbpfInsns[i].jf = C.u_char(v.Jf)
317: 		gbpfInsns[i].k = C.bpf_u_int32(v.K)
318: 	}
319: 
320: 	bpf.bf_insns = (*C.struct_bpf_insn)(cbpfInsns)
321: 	return bpf
322: }
