342: func (b *BPF) pcapOfflineFilter(ci gopacket.CaptureInfo, data []byte) bool {
343: 	hdr := (*C.struct_pcap_pkthdr)(&b.hdr)
344: 	hdr.ts.tv_sec = C.gopacket_time_secs_t(ci.Timestamp.Unix())
345: 	hdr.ts.tv_usec = C.gopacket_time_usecs_t(ci.Timestamp.Nanosecond() / 1000)
346: 	hdr.caplen = C.bpf_u_int32(len(data)) // Trust actual length over ci.Length.
347: 	hdr.len = C.bpf_u_int32(ci.Length)
348: 	dataptr := (*C.u_char)(unsafe.Pointer(&data[0]))
349: 	return C.pcap_offline_filter_escaping((*C.struct_bpf_program)(&b.bpf.bpf),
350: 		C.uintptr_t(uintptr(unsafe.Pointer(hdr))),
351: 		C.uintptr_t(uintptr(unsafe.Pointer(dataptr)))) != 0
352: }
