110: 
111: 	if preferredSrc == nil {
112: 		switch {
113: 		case dst.To4() != nil:
114: 			preferredSrc = r.addrs[ifaceIndex].v4
115: 		case dst.To16() != nil:
116: 			preferredSrc = r.addrs[ifaceIndex].v6
117: 		}
