175: 	for _, m := range msgs {
176: 		switch m.Header.Type {
177: 		case syscall.NLMSG_DONE:
178: 			break loop
179: 		case syscall.RTM_NEWROUTE:
180: 			rt := (*routeInfoInMemory)(unsafe.Pointer(&m.Data[0]))
